import{_ as o,o as e,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const u=JSON.parse('{"title":"Migração de processos PJe → eproc (TJMG)","description":"","frontmatter":{"title":"Migração de processos PJe → eproc (TJMG)","id":"eproc-migracao-pje","plataforma":"eproc","tribunal":"TJMG","grupo":"Migração PJe (TJMG)","plano":"free","desde":"1.2.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-migracao-pje"}]]},"headers":[],"relativePath":"funcionalidades/eproc-migracao-pje.md","filePath":"funcionalidades/eproc-migracao-pje.md"}'),t={name:"funcionalidades/eproc-migracao-pje.md"};function i(d,a,c,p,l,n){return e(),r("div",null,a[0]||(a[0]=[s('<h1 id="migracao-de-processos-pje-→-eproc-tjmg" tabindex="-1">Migração de processos PJe → eproc (TJMG) <a class="header-anchor" href="#migracao-de-processos-pje-→-eproc-tjmg" aria-label="Permalink to &quot;Migração de processos PJe → eproc (TJMG)&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Melhora a tela de importação de processos do PJe para o eproc do TJMG: resume o longo texto das regras de migração num menu expansível, mostra um gráfico com o progresso das migrações e, ao migrar um único processo, oferece abri-lo no eproc assim que a migração terminar.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc do TJMG</strong>, tela de importação de processos do PJe.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra a tela de importação de processos do PJe.</li><li>As regras de migração aparecem recolhidas num menu. Clique para expandi-las.</li><li>O gráfico mostra a evolução da quantidade de processos já migrados.</li><li>Ao informar um único processo, aparece ao lado do botão de importar a caixa &quot;Ao concluir, abrir o processo no eproc&quot;. Com ela marcada, o processo é aberto pela pesquisa rápida assim que a migração termina, inclusive quando o eproc responde &quot;Processo já migrado&quot;.</li></ol><p>A escolha da caixa fica salva para as próximas migrações.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Resumir regras de migração em menu expansível</td><td>ligada</td><td>Recolhe o texto das regras.</td></tr><tr><td>Exibir gráfico de progresso da migração</td><td>ligada</td><td>Mostra o gráfico.</td></tr><tr><td>Exibir a opção &quot;Ao concluir, abrir o processo no eproc&quot; ao migrar um único processo</td><td>ligada</td><td>Mostra a caixa ao lado do botão de importar.</td></tr><tr><td>Deixar a opção marcada (acompanha o checkbox da tela de importação)</td><td>ligada</td><td>Mesmo valor da caixa na tela. Só aparece com a opção anterior ligada.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O gráfico é montado com o que o eploc registrou nas suas visitas a essa tela, neste navegador.</li><li>A abertura automática só é oferecida quando o lote tem um único processo.</li></ul>',12)]))}const g=o(t,[["render",i]]);export{u as __pageData,g as default};
